  sealed class Source{public string Id,Name;public override string ToString(){return Name;}}
  void ConnectionsChanged(object s,EventArgs e){if(loading||editingStage==null)return;editingStage.Parent=((Source)parent.SelectedItem).Id;editingStage.SecondParent=((Source)secondParent.SelectedItem).Id;editingStage.PowerShare=(double)share.Value;editingStage.SecondPowerShare=(double)secondShare.Value;Changed();}
  void AddNumber(FlowLayoutPanel host,string key,string title,decimal min,decimal max,int digits,decimal step){host.Controls.Add(new Label{Text=title,AutoSize=true,Margin=new Padding(0,11,0,3)});var field=typeof(Parameters).GetProperty(key);var n=new SafeNumber{Minimum=min,Maximum=max,DecimalPlaces=digits,Increment=step,Width=285,AccessibleName=title};n.Commit(Math.Max(min,Math.Min(max,Convert.ToDecimal(field.GetValue(editingStage.Parameters,null)))));stageNumbers[key]=n;host.Controls.Add(n);n.ValueChanged+=(s,e)=>{if(!loading){if(CaptureStage())Changed();}};n.Leave+=(s,e)=>{if(!loading&&CaptureStage())Changed();};}
  bool CaptureStage(){string before=Snapshot();decimal motorRpm,motorTorque;if(!rpm.TryRead(out motorRpm)||!torque.TryRead(out motorTorque)){Error("Исправьте обороты / момент двигателя.");solution=null;return false;}document.InputRpm=(double)motorRpm;document.InputTorque=(double)motorTorque;if(editingStage==null)return true;var values=new Dictionary<string,decimal>();foreach(var pair in stageNumbers){decimal v;if(!pair.Value.TryRead(out v)){Error("Исправьте поле «"+pair.Value.AccessibleName+"» перед сохранением или экспортом.");solution=null;return false;}values[pair.Key]=v;}var pp=editingStage.Parameters;bool ratioChanged=values.ContainsKey("Ratio")&&Math.Abs(pp.Ratio-(double)values["Ratio"])>1e-10;bool sizeChanged=values.Any(pair=>pair.Key!="Ratio"&&pair.Key!="Efficiency"&&Math.Abs((double)typeof(Parameters).GetProperty(pair.Key).GetValue(pp,null)-(double)pair.Value)>1e-10);foreach(var pair in values)typeof(Parameters).GetProperty(pair.Key).SetValue(pp,(double)pair.Value,null);if(sizeChanged){pp.AutoFit=false;pp.Overall=0;}else if(ratioChanged&&pp.AutoFit&&pp.Overall>0){Engine.FitOverall(pp);loading=true;foreach(var pair in stageNumbers)pair.Value.Commit(Convert.ToDecimal(typeof(Parameters).GetProperty(pair.Key).GetValue(pp,null)));loading=false;}editingStage.Name=TransmissionCatalog.All[editingStage.Parameters.Kind].Name;if(!loading&&before!=Snapshot())Checkpoint();return true;}
  void AddMenu(){if(!CaptureStage())return;var menu=new ContextMenuStrip();foreach(var type in TransmissionCatalog.All){var copy=type;menu.Items.Add(copy.Name,null,(s,e)=>AddStage(copy.Id));}menu.Show(Cursor.Position);}
  internal void AddStage(int kind){if(!CaptureStage())return;bool chain=IsChain();int index=list.SelectedIndex<0?document.Stages.Count:list.SelectedIndex+1;var n=new TrainStage{Name=TransmissionCatalog.All[kind].Name,Parameters=Engine.Starter(kind),Parent=list.SelectedItem==null?null:((TrainStage)list.SelectedItem).Id};document.Stages.Insert(index,n);if(chain)Chain();Changed();Reload(n.Id);}
  void MoveStage(int delta){if(!CaptureStage())return;if(!IsChain()){Error("Перемещение доступно для последовательной цепи. Ветвления задаются источниками входа.");return;}int i=list.SelectedIndex,j=i+delta;if(i<0||j<0||j>=document.Stages.Count)return;var n=document.Stages[i];document.Stages.RemoveAt(i);document.Stages.Insert(j,n);Chain();Changed();Reload(n.Id);}
  void Duplicate(){if(editingStage==null||!CaptureStage())return;bool chain=IsChain();var n=new TrainStage{Name=editingStage.Name,Parameters=Engine.Clone(editingStage.Parameters),Parent=editingStage.Id};document.Stages.Insert(list.SelectedIndex+1,n);if(chain)Chain();Changed();Reload(n.Id);}
  void DeleteStage(){if(editingStage==null)return;if(document.Stages.Count==1){Error("В цепи должна остаться хотя бы одна ступень.");return;}var n=editingStage;bool chain=IsChain();if(!chain&&document.Stages.Any(x=>x.Parent==n.Id||x.SecondParent==n.Id)){Error("У ступени есть ответвления: сначала переназначьте их источники.");return;}document.Stages.Remove(n);editingStage=null;if(chain)Chain();Changed();Reload();}
  void AdvancedEditor(){if(!CaptureStage())return;var n=editingStage;using(var form=new MainForm()){form.ConfigureForTrain(n.Parameters,p=>{n.Parameters=Engine.Clone(p);n.Name=TransmissionCatalog.All[p.Kind].Name;form.WorkspaceApproveClose();form.Close();});form.ShowLocalizedDialog(this);}Changed();editingStage=null;SelectStage();}
  void Error(string text){status.ForeColor=Color.Firebrick;status.Text=text;summary.Text="Проверьте параметры цепи";timer.Stop();}
  void UpdateMath(){if(!CaptureStage())return;var quick=TrainSolver.Solve(document,false);solution=quick;if(!quick.Valid){Error(string.Join("; ",quick.Errors));viewer.SetResult(null,true);list.Invalidate();return;}ShowSolution(quick);}
  void ShowSolution(TrainSolution s){table.Rows.Clear();foreach(var n in document.Stages){TrainState st;if(!s.States.TryGetValue(n.Id,out st))continue;bool linear=st.Result.Engineering!=null&&st.Result.Engineering.Linear;table.Rows.Add((document.Stages.IndexOf(n)+1)+". "+st.Name,Engine.F(st.InputRpm),Engine.F(linear?st.LinearSpeed:st.OutputRpm),Engine.F(linear?st.OutputForce:st.OutputTorque),Engine.F(st.Efficiency),Engine.F(st.OutputPower));}var leaves=s.States.Values.Where(st=>!document.Stages.Any(n=>n.Parent==st.Id||n.SecondParent==st.Id)).ToList();summary.Text=string.Join("\n",leaves.Select(st=>st.Result.Engineering!=null&&st.Result.Engineering.Linear?"ВЫХОД  "+Engine.F(st.LinearSpeed)+" мм/с · "+Engine.F(st.OutputForce)+" Н":"ВЫХОД  i = "+(Math.Abs(st.OutputGain)<1e-12?"∞":Engine.F(1/Math.Abs(st.OutputGain)))+"    "+Engine.F(st.OutputRpm)+" об/мин    "+Engine.F(st.OutputTorque)+" Н·м"));status.ForeColor=Color.FromArgb(33,109,92);status.Text="Изменения применены · "+document.Stages.Count+" ступени. Моменты рассчитаны с учётом заданного КПД.\nПроверка прочности и допустимых нагрузок выполняется отдельно.";list.Invalidate();}
  void Calculate(){rebuild.Stop();if(!CaptureStage()){solution=null;return;}decimal a,b;if(!rpm.TryRead(out a)||!torque.TryRead(out b)){Error("Проверьте числа двигателя.");solution=null;return;}document.InputRpm=(double)a;document.InputTorque=(double)b;timer.Stop();solution=TrainSolver.Solve(document);if(!solution.Valid){Error(string.Join("; ",solution.Errors));viewer.SetResult(null,true);return;}phase=0;viewer.SetResult(solution.Scene,true);ShowSolution(solution);}
  internal void ExportStlFile(string target){if(busy)throw new Exception("Дождитесь STEP-экспорта.");Calculate();if(solution==null||!solution.Valid)throw new Exception("Исправьте параметры и связи перед экспортом.");PrintExport.Zip(PrintExport.Select(solution.Scene.Model,null),target);}
  void Save(){if(!CaptureStage())return;var check=TrainSolver.Solve(document,false);if(!check.Valid){Error(string.Join("; ",check.Errors));return;}using(var d=new SaveFileDialog{Filter="Цепь GearLab|*.train.json",FileName=path??"Редуктор.train.json"})if(d.ShowLocalizedDialog(this)==DialogResult.OK){document.Save(d.FileName);path=d.FileName;dirty=false;status.Text="Сохранено: "+path;}}
  void Replace(TransmissionTrain value){if(!WorkspaceCanClose())return;document=Copy(value);editingStage=null;path=null;dirty=false;undo.Clear();redo.Clear();previous=Snapshot();Reload();Calculate();}
  void Open(){if(!WorkspaceCanClose())return;using(var d=new OpenFileDialog{Filter="Цепь GearLab|*.train.json"})if(d.ShowLocalizedDialog(this)==DialogResult.OK)try{var next=TransmissionTrain.Read(d.FileName);document=next;editingStage=null;path=d.FileName;dirty=false;undo.Clear();redo.Clear();previous=Snapshot();Reload();Calculate();}catch(Exception ex){Error(ex.Message);}}
  void History(bool forward){if(busy)return;var from=forward?redo:undo;var to=forward?undo:redo;if(from.Count==0)return;to.Push(Snapshot());document=CADDocument.Serializer().Deserialize<TransmissionTrain>(from.Pop());previous=Snapshot();editingStage=null;dirty=true;Reload();Calculate();}
  async void Export(){if(busy)return;Calculate();if(solution==null||!solution.Valid)return;using(var d=new SaveFileDialog{Filter="STEP|*.step"})if(d.ShowLocalizedDialog(this)==DialogResult.OK){string target=d.FileName,temp=target+"."+Guid.NewGuid().ToString("N")+".tmp";busy=true;try{var model=solution.Scene.Model;status.Text="Строится точный STEP…";await System.Threading.Tasks.Task.Factory.StartNew(()=>TransmissionExport.Write(model,temp,kernel));if(File.Exists(target))File.Replace(temp,target,null);else File.Move(temp,target);status.Text="STEP сохранён: "+target;}catch(Exception ex){Error(ex.GetBaseException().Message);}finally{busy=false;if(File.Exists(temp))File.Delete(temp);}}}
  public bool WorkspaceCanClose(){if(!CaptureStage())return false;if(busy){Error("Дождитесь STEP-экспорта или отмените его.");return false;}if(!dirty)return true;var ans=UiMessage.Show(this,"Сохранить цепь ступеней?","Проект",MessageBoxButtons.YesNoCancel);if(ans==DialogResult.Cancel)return false;if(ans==DialogResult.Yes){Save();return !dirty;}return true;}public void WorkspaceApproveClose(){approved=true;}public void WorkspaceActivate(bool active){if(!active)timer.Stop();}
